CREATE TABLE IF NOT EXISTS v202_jobs(attempt_id text PRIMARY KEY REFERENCES v20_attempts(id),pending boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION v202_queue_diagnosis() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
IF NEW.status='graded' THEN INSERT INTO v202_jobs(attempt_id) VALUES(NEW.id) ON CONFLICT(attempt_id) DO UPDATE SET pending=true,updated_at=now();END IF;RETURN NEW;END $$;
DROP TRIGGER IF EXISTS v202_after_grade ON v20_attempts;
CREATE TRIGGER v202_after_grade AFTER INSERT OR UPDATE OF status,score,feedback ON v20_attempts FOR EACH ROW EXECUTE FUNCTION v202_queue_diagnosis();
CREATE TABLE IF NOT EXISTS v202_diagnostics(attempt_id text PRIMARY KEY REFERENCES v20_attempts(id),revision text NOT NULL,status text NOT NULL,summary jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS v202_loops(id text PRIMARY KEY,attempt_id text NOT NULL REFERENCES v20_attempts(id),skill_key text NOT NULL,unit int NOT NULL,objective text NOT NULL,kind text NOT NULL,diagnosis jsonb NOT NULL,anchors jsonb NOT NULL,resources jsonb NOT NULL,verification jsonb NOT NULL DEFAULT '[]',state text NOT NULL DEFAULT 'recommended',source_changed boolean NOT NULL DEFAULT false,error text NOT NULL DEFAULT '',lease_token text,lease_at timestamptz,teacher_note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(attempt_id,skill_key));
CREATE TABLE IF NOT EXISTS v202_steps(id text PRIMARY KEY,loop_id text NOT NULL REFERENCES v202_loops(id),stage text NOT NULL CHECK(stage IN ('practice','verify')),questions jsonb NOT NULL,answers jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','grading','graded','review')),score numeric,marks jsonb NOT NULL DEFAULT '[]',error text NOT NULL DEFAULT '',lease_token text,lease_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),submitted_at timestamptz,graded_at timestamptz,UNIQUE(loop_id,stage));
CREATE TABLE IF NOT EXISTS v202_events(id text PRIMARY KEY,loop_id text REFERENCES v202_loops(id),attempt_id text NOT NULL REFERENCES v20_attempts(id),actor_id text NOT NULL,action text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS v202_loop_attempt ON v202_loops(attempt_id);
CREATE INDEX IF NOT EXISTS v202_event_attempt ON v202_events(attempt_id,created_at);
INSERT INTO v202_jobs(attempt_id) SELECT t.id FROM v20_attempts t JOIN v20_assessments a ON a.id=t.assessment_id WHERE t.status='graded' AND NOT a.practice ON CONFLICT DO NOTHING;
